// ─── File: MigrationDemo.java ───
// Runnable demo: coexistence → shadow → reconcile → ramp authority.
package com.bank.migration;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.*;

public class MigrationDemo {

    private static final Logger log = Logger.getLogger("Migration");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Ledger real = new Ledger(); Ledger shadow = new Ledger();
        for (String id : List.of("SAV2001", "CUR3001")) {
            real.set(id, new BigDecimal("500000"));
            shadow.set(id, new BigDecimal("500000"));
        }
        EventBus bus = new EventBus();
        ShadowConsumer shadowConsumer = new ShadowConsumer(shadow);
        bus.subscribe(shadowConsumer::onEvent);

        FeatureFlag flag = new FeatureFlag();           // REST authoritative, 0% ramp
        RestTransferProcessor rest = new RestTransferProcessor(real, bus, flag);

        // ---- Stage 1-2: REST authoritative, Kafka shadow ----
        rest.transfer("TXF-1", "SAV2001", "CUR3001", new BigDecimal("50000"));
        rest.transfer("TXF-2", "CUR3001", "SAV2001", new BigDecimal("20000"));
        // Simulate duplicate event delivery — idempotency must absorb it.
        bus.publish(new TransferEvent("TXF-1", "SAV2001", "CUR3001",
                new BigDecimal("50000")));

        // ---- Stage 3: reconcile real vs shadow ----
        Reconciler reconciler = new Reconciler();
        boolean equivalent = reconciler.reconcile(real, shadow,
                List.of("SAV2001", "CUR3001"));
        log.info(() -> "Reconciliation equivalent = " + equivalent);

        // ---- Stage 4: ramp authority to the event path ----
        if (equivalent) {
            flag.setEventAuthoritative(true);
            flag.setRampPercent(10);
            log.info(() -> "Authority ramped: event path now authoritative for "
                    + flag.rampPercent() + "% of traffic");
        }
    }
}

// ─── event/TransferEvent.java ───
record TransferEvent(String transferId, String fromId, String toId, BigDecimal amount) { }

// ─── rest/RestTransferProcessor.java (authoritative synchronous path) ───
class RestTransferProcessor {
    private static final Logger log = Logger.getLogger("Migration");
    private final Ledger real;
    private final EventBus bus;
    private final FeatureFlag flag;
    RestTransferProcessor(Ledger real, EventBus bus, FeatureFlag flag) {
        this.real = real; this.bus = bus; this.flag = flag;
    }
    void transfer(String id, String from, String to, BigDecimal amount) {
        // If authority has moved to the event path for this request, REST does NOT
        // perform the business action (prevents double execution). Here flag is off.
        if (flag.isEventAuthoritativeFor(id)) {
            log.info(() -> "REST skips " + id + " — event path authoritative");
            bus.publish(new TransferEvent(id, from, to, amount));
            return;
        }
        real.debit(from, amount);
        real.credit(to, amount);
        log.info(() -> "REST (authoritative) applied " + id + " Rs." + amount);
        // Publish the same operation as an event (ideally via outbox) for shadow.
        bus.publish(new TransferEvent(id, from, to, amount));
    }
}

// ─── shadow/ShadowConsumer.java (idempotent event path) ───
class ShadowConsumer {
    private static final Logger log = Logger.getLogger("Migration");
    private final Ledger shadow;
    private final Map<String, Boolean> processed = new ConcurrentHashMap<>();
    ShadowConsumer(Ledger shadow) { this.shadow = shadow; }
    void onEvent(TransferEvent e) {
        // Idempotency: first delivery wins; duplicates are skipped.
        if (processed.putIfAbsent(e.transferId(), Boolean.TRUE) != null) {
            log.info(() -> "SHADOW duplicate " + e.transferId() + " skipped");
            return;
        }
        shadow.debit(e.fromId(), e.amount());
        shadow.credit(e.toId(), e.amount());
        log.info(() -> "SHADOW applied " + e.transferId() + " Rs." + e.amount());
    }
}

// ─── recon/Reconciler.java ───
class Reconciler {
    private static final Logger log = Logger.getLogger("Migration");
    boolean reconcile(Ledger real, Ledger shadow, List<String> accounts) {
        for (String id : accounts) {
            if (real.get(id).compareTo(shadow.get(id)) != 0) {
                log.severe("DIVERGENCE on " + id + ": real " + real.get(id)
                        + " vs shadow " + shadow.get(id));
                return false;
            }
        }
        return true;
    }
}

// ─── flag/FeatureFlag.java ───
class FeatureFlag {
    private volatile boolean eventAuthoritative = false;
    private volatile int rampPercent = 0;
    void setEventAuthoritative(boolean v) { this.eventAuthoritative = v; }
    void setRampPercent(int p) { this.rampPercent = p; }
    int rampPercent() { return rampPercent; }
    // Deterministic per-id bucketing so a given transfer always routes the same way.
    boolean isEventAuthoritativeFor(String id) {
        return eventAuthoritative && (Math.floorMod(id.hashCode(), 100) < rampPercent);
    }
}

class Ledger {
    private final Map<String, BigDecimal> db = new ConcurrentHashMap<>();
    void set(String id, BigDecimal b) { db.put(id, b); }
    void debit(String id, BigDecimal amt) { db.merge(id, amt.negate(), BigDecimal::add); }
    void credit(String id, BigDecimal amt) { db.merge(id, amt, BigDecimal::add); }
    BigDecimal get(String id) { return db.get(id); }
}

class EventBus {
    private final List<java.util.function.Consumer<TransferEvent>> subs =
            new java.util.ArrayList<>();
    void subscribe(java.util.function.Consumer<TransferEvent> c) { subs.add(c); }
    void publish(TransferEvent e) { subs.forEach(c -> c.accept(e)); }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
